/**
 * A message from the public site: a contact message, a waitlist sign-up or an info request. Anyone can send one, signed in or not; system admins list them.
 */
export type Request = {
  createdAt: string;
  id: string;
  message: string | null;
  email: string;
  kind: 'waitlist' | 'info' | 'contact';
  invited: boolean;
};

/**
 * An actor that is not a person, in one tenant: API keys run as it, and it holds role bindings like a member holds memberships. An organization admin creates one, for example with Create API key in organization settings.
 */
export type ServiceAccount = {
  id: string;
  tenantId: string;
  name: string;
  status: 'pending' | 'active' | 'disabled';
  bindings: Array<{
    channelType: 'organization';
    channelId: string;
    organizationId: string;
    role: 'admin' | 'member';
  }>;
  oauthClientId: string | null;
  connectionId: string | null;
  createdAt: string;
  createdBy:
    | {
        id: string;
        name: string;
        thumbnailUrl: string | null;
        kind: 'user';
        slug: string;
      }
    | {
        id: string;
        name: string;
        thumbnailUrl: string | null;
        kind: 'service';
        slug: null;
      }
    | null;
  updatedAt: string | null;
  updatedBy:
    | {
        id: string;
        name: string;
        thumbnailUrl: string | null;
        kind: 'user';
        slug: string;
      }
    | {
        id: string;
        name: string;
        thumbnailUrl: string | null;
        kind: 'service';
        slug: null;
      }
    | null;
  role: 'admin' | 'member';
  lastSeenAt: string | null;
};

/**
 * A secret key a service account authenticates with, sent as `Authorization: Bearer` or `x-api-key`. Only its prefix and last four characters are returned after creation; it can expire and be revoked.
 */
export type ApiKey = {
  id: string;
  actorId: string;
  tenantId: string;
  name: string;
  prefix: string;
  last4: string;
  scopes: Array<'organization:read' | 'organization:write' | 'attachment:read' | 'attachment:write'> | null;
  expiresAt: string | null;
  revokedAt: string | null;
  createdBy:
    | {
        id: string;
        name: string;
        thumbnailUrl: string | null;
        kind: 'user';
        slug: string;
      }
    | {
        id: string;
        name: string;
        thumbnailUrl: string | null;
        kind: 'service';
        slug: null;
      }
    | null;
  createdAt: string;
};

/**
 * The top-level isolation and billing boundary. Tenant and organization are 1:1: a tenant holds one organization, or none until that organization is created. System admins list and update tenants; a signed-in user can create one of their own.
 */
export type Tenant = {
  id: string;
  name: string;
  /**
   * What the tenant is for: `live` serves customers, `test` staff and automated runs, `demo` a visitor.
   */
  kind: 'live' | 'test' | 'demo';
  status: 'active' | 'suspended' | 'deleted';
  statusChangedAt: string;
  /**
   * When the tenant goes with everything in it; a demo always carries one.
   */
  expiresAt: string | null;
  restrictions: {
    /**
     * Caps per tenant on entities, service accounts, API keys and LTI connections (0 = unlimited)
     */
    quotas: {
      user: number;
      organization: number;
      attachment: number;
      serviceAccount: number;
      apiKey: number;
      ltiConnection: number;
    };
    rateLimits: {
      /**
       * Max API points per hour per actor within this tenant (0 = no tenant limit; the global safety ceiling still applies)
       */
      apiPointsPerHour: number;
      /**
       * Max invitation mails per day the tenant sends, new and resent alike (0 = no cap)
       */
      invitationEmailsPerDay: number;
    };
    /**
     * Whether members may consent to OAuth clients that have no registration (AI clients using a Client ID Metadata Document)
     */
    allowUnregisteredClients: boolean;
  };
  authStrategies: Array<'github' | 'google' | 'microsoft' | 'passkey' | 'totp' | 'email' | 'magic' | 'anonymous' | 'lti' | 'surfconext'>;
  createdAt: string;
  createdBy:
    | {
        id: string;
        name: string;
        thumbnailUrl: string | null;
        kind: 'user';
        slug: string;
      }
    | {
        id: string;
        name: string;
        thumbnailUrl: string | null;
        kind: 'service';
        slug: null;
      }
    | null;
  updatedAt: string | null;
  updatedBy:
    | {
        id: string;
        name: string;
        thumbnailUrl: string | null;
        kind: 'user';
        slug: string;
      }
    | {
        id: string;
        name: string;
        thumbnailUrl: string | null;
        kind: 'service';
        slug: null;
      }
    | null;
  /**
   * The organization this tenant holds, or null if none
   */
  organization: {
    id: string;
    name: string;
    slug: string;
    thumbnailUrl: string | null;
    entityType: 'organization';
  } | null;
};

/**
 * A tenant's trust in an external party that asserts user identities: an institution reached through an SSO federation, whose members sign in to the tenant's organization (`sso`), or an LTI platform the app registered at, which launches it (`lti`). An SSO connection's id is the public key of the tenant's SSO entry page. System admins manage SSO connections per tenant, `pending` until the institution activated the service at the federation; organization admins register LTI connections.
 */
export type Connection = {
  id: string;
  tenantId: string;
  kind: 'sso' | 'lti';
  federation: string | null;
  issuer: string | null;
  clientId: string | null;
  claimValues: Array<string>;
  name: string;
  status: 'pending' | 'active' | 'disabled';
  jitProvisioning: boolean;
  config:
    | {
        /**
         * The platform's OIDC authorization endpoint, where a launch's login goes
         */
        authorizationEndpoint: string;
        /**
         * The platform's token endpoint, for its services
         */
        tokenEndpoint: string;
        /**
         * The audience of a token request at the platform, when it names one apart from its token endpoint
         */
        authorizationServer?: string;
        /**
         * The platform's key set, which signs its launches
         */
        jwksUri: string;
        /**
         * The platform's address of this registration, when it gave one
         */
        registrationClientUri?: string;
        /**
         * The platform's product, such as `canvas` or `moodle`
         */
        productFamilyCode: string;
        /**
         * The platform's version
         */
        version: string;
        /**
         * The LTI deployment a launch must name: the one the registration returned, else the first launch; empty before either
         */
        deploymentIds: Array<string>;
      }
    | {
        /**
         * The institution's IdP entity ids, passed as login_hint
         */
        idpEntityIds?: Array<string>;
        /**
         * The institution's logo, for the entry page
         */
        logoUrl?: string;
      };
  createdAt: string;
  createdBy:
    | {
        id: string;
        name: string;
        thumbnailUrl: string | null;
        kind: 'user';
        slug: string;
      }
    | {
        id: string;
        name: string;
        thumbnailUrl: string | null;
        kind: 'service';
        slug: null;
      }
    | null;
  updatedAt: string | null;
  updatedBy:
    | {
        id: string;
        name: string;
        thumbnailUrl: string | null;
        kind: 'user';
        slug: string;
      }
    | {
        id: string;
        name: string;
        thumbnailUrl: string | null;
        kind: 'service';
        slug: null;
      }
    | null;
};

export type ListAttachmentsData = {
  body?: never;
  headers?: {
    /**
     * The `rangeKey` of the change frame that caused a range read (`afterSeq`, `untilSeq`): the read may then take the answer just given to a reader of the same rows.
     */
    'x-range-key'?: string;
  };
  path: {
    tenantId: string;
    organizationId: string;
  };
  query?: {
    /**
     * The previous page's `nextPageToken`. Every other param except `maxPageSize` and `skip` must match the request that returned it.
     */
    pageToken?: string;
    /**
     * Most results one page holds. Absent or 0 reads 40; above 1000 reads 1000. A page may hold fewer.
     */
    maxPageSize?: number;
    /**
     * Results to pass over after the page token's position, or from the start without a token.
     */
    skip?: number;
    /**
     * Search, case- and accent-insensitive. Every word must appear in a searched field; "quotes" keep a phrase together and a leading - leaves out items holding that whole word or phrase.
     */
    q?: string;
    /**
     * Range read for sync: return the rows stamped after this sequence position. Requires untilSeq.
     */
    afterSeq?: number;
    /**
     * Range read for sync: the last sequence position to return. Requires afterSeq.
     */
    untilSeq?: number;
    /**
     * A field to order by, then `asc` or `desc`; ascending when left out.
     */
    orderBy?:
      | 'name'
      | 'name asc'
      | 'name desc'
      | 'createdAt'
      | 'createdAt asc'
      | 'createdAt desc'
      | 'contentType'
      | 'contentType asc'
      | 'contentType desc';
    channelId?: string;
  };
  url: '/tenants/{tenantId}/organizations/{organizationId}/attachments';
};

